/*Table structure for table `tb_handbooks` */

CREATE TABLE `tb_handbooks` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fish_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鱼种名称',
  `fish_alias` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '别名',
  `category` enum('freshwater','saltwater','shrimp_crab','special') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类',
  `cover_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图',
  `brief_intro` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '简介',
  `difficulty` enum('easy','medium','hard') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '养殖难度',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容（富文本HTML）',
  `is_published` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否发布：0否,1是',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_is_published` (`is_published`),
  KEY `idx_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='养殖手册表';

/*Data for the table `tb_handbooks` */

insert  into `tb_handbooks`(`id`,`fish_name`,`fish_alias`,`category`,`cover_image`,`brief_intro`,`difficulty`,`content`,`is_published`,`sort_order`,`view_count`,`create_time`,`update_time`) values (1,'草鱼','鲩鱼、草鲩、白鲩','freshwater','','草鱼是我国四大家鱼之一，生长快，饲料来源广，是我国主要养殖对象.','easy','<h2>一、生物学特性</h2>\n<p>草鱼属鲤形目鲤科雅罗鱼亚科草鱼属。体长，略呈圆筒形，腹部无棱。头部平扁，尾部侧扁。下咽齿2行，呈梳状。体呈茶黄色，腹部灰白色，体侧鳞片边缘灰黑色，胸鳍、腹鳍灰黄色，其他鳍较深。</p>\n<h2>二、生活习性</h2>\n<p>草鱼栖息于江河、湖泊的中、下层水域。性活泼，游泳迅速，常成群觅食。为典型的草食性鱼类，幼鱼期食幼虫、藻类等，成鱼期摄食水生高等植物，尤喜食苏丹草、黑麦草等。</p>\n<h2>三、养殖技术要点</h2>\n<h3>1. 池塘条件</h3>\n<ul>\n<li>面积：5-10亩为宜</li>\n<li>水深：2-3米</li>\n<li>底质：淤泥厚度不超过20cm</li>\n<li>水源：充足、清新、无污染</li>\n</ul>\n<h3>2. 放养密度</h3>\n<p>主养草鱼：每亩放养规格为150-250g的草鱼种800-1000尾，搭配鲢鱼200-300尾，鳙鱼50-80尾，鲫鱼50尾。</p>\n<h3>3. 饲料投喂</h3>\n<ul>\n<li>饲料种类：青饲料和精饲料结合</li>\n<li>投喂量：根据水温、天气和鱼的摄食情况而定</li>\n<li>投喂次数：每天2-3次</li>\n<li>投喂原则：定时、定位、定质、定量</li>\n</ul>\n<h3>4. 水质管理</h3>\n<ul>\n<li>定期加注新水，保持水质清新</li>\n<li>合理使用增氧机，防止缺氧</li>\n<li>定期泼洒生石灰，调节水质</li>\n<li>监测水质指标：pH值7-8.5，溶氧>5mg/L</li>\n</ul>\n<h3>5. 病害防治</h3>\n<p><strong>常见病害：</strong>赤皮病、烂鳃病、肠炎病（\"老三病\"）</p>\n<p><strong>预防措施：</strong></p>\n<ul>\n<li>彻底清塘消毒</li>\n<li>鱼种消毒后下塘</li>\n<li>定期投喂药饵</li>\n<li>保持良好水质</li>\n</ul>\n<h2>四、经济效益</h2>\n<p>养殖周期：12-18个月<br>\n上市规格：3-5斤/尾<br>\n亩产量：800-1200斤<br>\n成本：约5000-6000元/亩<br>\n收益：约8000-12000元/亩<br>\n净利润：约3000-6000元/亩</p>',1,1,170,'2026-04-22 15:12:19','2026-05-24 19:56:47'),(2,'鲢鱼','白鲢、水鲢、跳鲢','freshwater','','鲢鱼是著名的四大家鱼之一，是我国主要的淡水养殖鱼类.','easy','<h2>一、生物学特性</h2>\n<p>鲢鱼体侧扁，稍高，呈纺锤形。头大，约为体长的1/4。眼小，位于头的下半部。鳞细小。背部青灰色，体侧及腹部白色。</p>\n<h2>二、生活习性</h2>\n<p>鲢鱼属中上层鱼类，性活泼，善跳跃。滤食性，主要摄食浮游植物，也摄食部分浮游动物。在人工饲养条件下，可摄食豆浆、麸皮、米糠等。</p>\n<h2>三、养殖技术</h2>\n<h3>1. 混养模式</h3>\n<p>鲢鱼常作为配养鱼类，与草鱼、鳙鱼、鲤鱼等混养。一般每亩放养200-400尾。</p>\n<h3>2. 水质要求</h3>\n<ul>\n<li>喜肥水，要求水质肥而活</li>\n<li>适宜pH值：7.5-8.5</li>\n<li>溶氧量：>3mg/L</li>\n</ul>\n<h3>3. 投喂管理</h3>\n<p>除天然饵料外，可投喂豆浆、麸皮、米糠等。投喂量根据水温和鱼的生长情况调整。</p>\n<h2>四、经济价值</h2>\n<p>养殖周期：1-2年<br>\n上市规格：2-4斤/尾<br>\n市场价格：5-7元/斤<br>\n养殖效益：稳定可观</p>',1,2,266,'2026-04-22 15:12:19','2026-05-23 10:22:01'),(3,'鳙鱼','花鲢、胖头鱼、大头鱼','freshwater','','鳙鱼头大，约占体长的1/3，是淡水养殖的重要品种.','easy','<h2>一、基本特征</h2>\n<p>鳙鱼体侧扁，头极肥大。口大，端位，下颌稍向上倾斜。体侧及腹部灰白色，有许多浅黄色及黑色的不规则小斑点。</p>\n<h2>二、养殖特点</h2>\n<p>鳙鱼属中上层鱼类，性温驯，不爱跳跃。滤食性，主要摄食浮游动物（如轮虫、枝角类、桡足类等）。</p>\n<h2>三、养殖管理</h2>\n<h3>1. 放养搭配</h3>\n<p>通常作为配养鱼，每亩放养50-100尾，与草鱼、鲢鱼混养。</p>\n<h3>2. 水质培肥</h3>\n<p>定期施用有机肥料，培育浮游动物。保持水质\"肥、活、嫩、爽\"。</p>\n<h3>3. 日常管理</h3>\n<ul>\n<li>巡塘观察鱼的活动情况</li>\n<li>及时清除残饵、污物</li>\n<li>注意防病治病</li>\n</ul>\n<h2>四、养殖效益</h2>\n<p>生长速度较快，2龄鱼可达3-5斤。市场价格稳定，养殖效益好。</p>',1,3,77,'2026-04-22 15:12:19','2026-05-23 10:22:07'),(4,'鲤鱼','鲤拐子、鲤子','freshwater','','鲤鱼是我国最古老的养殖鱼类之一，适应性强，易于养殖.','easy','<h2>一、生物学特性</h2>\n<p>鲤鱼体侧扁而腹部圆，口呈马蹄形，须2对。体侧扁，背部苍黑色，腹部黄白色，尾鳍下叶橙红色。</p>\n<h2>二、生活习性</h2>\n<p>鲤鱼属底层鱼类，性温和，杂食性，自然条件下以底栖动物为食。人工养殖可投喂配合饲料。</p>\n<h2>三、养殖技术</h2>\n<h3>1. 放养模式</h3>\n<p>可以主养或混养。主养时每亩放养1000-1500尾，混养时每亩50-100尾。</p>\n<h3>2. 饲养管理</h3>\n<ul>\n<li>饵料：配合饲料为主</li>\n<li>投喂：每日2-3次</li>\n<li>日投饵量：体重的3-5%</li>\n</ul>\n<h3>3. 病害防治</h3>\n<p>常见病：竖鳞病、痘疮病、锚头鳋病等。预防为主，加强水质管理。</p>\n<h2>四、市场前景</h2>\n<p>鲤鱼肉质细嫩，营养丰富，市场需求量大，养殖效益稳定。</p>',1,4,98,'2026-04-22 15:12:19','2026-05-23 10:22:03'),(5,'鲫鱼','鲫瓜子、月鲫仔','freshwater','','鲫鱼适应性极强，是池塘养殖的常见品种.','easy','<h2>一、品种特点</h2>\n<p>鲫鱼体侧扁而高，头小，吻钝。无须。体背部为灰黑色，腹部银白色。</p>\n<h2>二、养殖优势</h2>\n<ul>\n<li>适应性强：耐低温、耐低氧</li>\n<li>食性杂：荤素兼食</li>\n<li>生长快：工程鲫等优良品种生长迅速</li>\n<li>抗病力强：成活率高</li>\n</ul>\n<h2>三、养殖模式</h2>\n<h3>1. 主养模式</h3>\n<p>亩放养规格10-20g的鱼种1500-2000尾。</p>\n<h3>2. 混养模式</h3>\n<p>作为配养鱼，每亩放养50-100尾。</p>\n<h3>3. 网箱养殖</h3>\n<p>适合在水库、湖泊进行网箱养殖。</p>\n<h2>四、养殖技术</h2>\n<ul>\n<li>投喂：配合饲料为主</li>\n<li>水质：保持清新，定期换水</li>\n<li>防病：注意预防寄生虫病</li>\n</ul>',1,5,9999,'2026-04-22 15:12:19','2026-05-23 10:22:04'),(6,'鲈鱼','花鲈、鲈板、七星鲈','freshwater','','鲈鱼是名贵经济鱼类，肉质鲜美，市场价值高.','medium','<h2>一、品种介绍</h2>\n<p>主要养殖品种：加州鲈鱼、海鲈鱼。加州鲈鱼生长快，适合池塘养殖；海鲈鱼肉质更佳，适合咸淡水养殖。</p>\n<h2>二、养殖条件</h2>\n<h3>1. 池塘要求</h3>\n<ul>\n<li>面积：3-8亩</li>\n<li>水深：1.5-2.5米</li>\n<li>底质：沙质或沙泥底</li>\n<li>配套：增氧、投饵设备齐全</li>\n</ul>\n<h3>2. 水质要求</h3>\n<ul>\n<li>水温：18-30℃为生长适温</li>\n<li>溶氧：>5mg/L</li>\n<li>pH值：7.0-8.5</li>\n<li>透明度：30-40cm</li>\n</ul>\n<h2>三、放养与投喂</h2>\n<h3>1. 放养</h3>\n<p>亩放养3-5cm规格鱼苗3000-5000尾，或10-15cm鱼种1000-1500尾。</p>\n<h3>2. 饲料</h3>\n<p>前期：投喂鲜活饵料（小杂鱼、虾等）<br>\n中后期：逐步驯化转食人工配合饲料</p>\n<h3>3. 投喂管理</h3>\n<ul>\n<li>日投喂2-3次</li>\n<li>日投饵率：5-8%（根据水温调整）</li>\n<li>投喂地点：固定食台</li>\n</ul>\n<h2>四、养殖效益</h2>\n<p>养殖周期：8-12个月<br>\n上市规格：0.8-1.5斤/尾<br>\n亩产量：1500-2500斤<br>\n市场价格：15-25元/斤<br>\n亩利润：15000-30000元</p>',1,6,235,'2026-04-22 15:12:19','2026-05-23 10:22:00');

/*Table structure for table `tb_help_content` */

CREATE TABLE `tb_help_content` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category` varchar(50) NOT NULL COMMENT '分类：quick-start/publish-guide/safety-tips/contact-us',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `content` text COMMENT '内容（支持HTML）',
  `sort_order` int DEFAULT '0' COMMENT '排序号（数字越小越靠前）',
  `status` varchar(20) DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-禁用',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='帮助内容表';

/*Data for the table `tb_help_content` */

insert  into `tb_help_content`(`id`,`category`,`title`,`content`,`sort_order`,`status`,`create_time`,`update_time`) values (16,'quick-start','第一步：浏览信息','<ul><li>在首页查看最新发布的<strong>供应信息</strong>和<strong>求购信息</strong></li><li>通过顶部导航进入<strong>供应信息</strong>或<strong>求购信息</strong>页面，使用筛选功能精确查找</li><li>进入<strong>物流服务</strong>页面，查找可靠的运输资源</li></ul>',1,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(17,'quick-start','第二步：发布信息','<ul><li>点击导航栏<strong>\"管理信息\"</strong>按钮进入管理页面</li><li>选择<strong>\"发布供应信息\"</strong>或<strong>\"发布求购信息\"</strong></li><li>填写完整的鱼苗品种、规格、数量、价格等信息</li><li>上传清晰的图片</li><li>提交后等待管理员审核</li></ul>',2,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(18,'quick-start','第三步：联系交易','<ul><li>找到感兴趣的信息后，点击<strong>查看电话</strong>联系对方</li><li>建议<strong>实地考察</strong>后再进行交易</li><li>签订正式合同，保留交易凭证</li></ul>',3,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(19,'publish-guide','供应信息发布','<ul><li>详细说明鱼苗的<strong>品种、规格、数量</strong></li><li>注明<strong>价格和价格单位</strong>（如元/尾、元/万尾）</li><li>填写准确的<strong>地址信息</strong></li><li>上传<strong>清晰的实拍图片</strong></li></ul>',1,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(20,'publish-guide','求购信息发布','<ul><li>明确说明需要的<strong>鱼苗品种和规格</strong></li><li>注明预期的<strong>价格区间</strong></li><li>说明<strong>交货时间和地点要求</strong></li><li>填写<strong>需求数量</strong></li></ul>',2,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(21,'publish-guide','物流信息发布','<ul><li>详细填写<strong>车辆信息和载重量</strong></li><li>标明<strong>服务范围和运输路线</strong></li><li>说明<strong>特殊运输设备</strong>（冷藏、增氧等）</li><li>提供合理的<strong>运费报价</strong></li></ul>',3,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(22,'safety-tips','谨防低价陷阱','<strong>价格明显低于市场价的信息需要谨慎，建议实地考察</strong>',1,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(23,'safety-tips','核实对方身份','<strong>交易前请核实对方的营业执照、身份证等相关证件</strong>',2,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(24,'safety-tips','选择安全付款','<strong>建议使用担保交易或货到付款，避免预付全款</strong>',3,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(25,'safety-tips','签订正式合同','<strong>签订正式的买卖合同，保留交易记录和凭证</strong>',4,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(26,'safety-tips','优先本地交易','<strong>优先选择本地交易，方便实地查看鱼苗质量</strong>',5,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(27,'contact-us','客服热线','<strong>电话：400-xxx-xxxx</strong><br/>工作时间：周一至周五 9:00-18:00',1,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(28,'contact-us','电子邮箱','<strong>邮箱：support@fishseedling.com</strong><br/>我们会在24小时内回复您的邮件',2,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(29,'contact-us','微信客服','<strong>微信号：fish_seedling_kf</strong><br/>扫描二维码或搜索微信号添加客服',3,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02'),(30,'contact-us','意见反馈','<strong>欢迎提出宝贵意见！</strong><br/>请通过邮件或客服热线告诉我们您的建议和问题',4,'enabled','2026-05-25 00:32:02','2026-05-25 00:32:02');

